cd /app/submission && python3 -m py_compile main.py && echo "compiles OK" && python3 - <<'PYEOF'
import ast, sys
tree = ast.parse(open('main.py').read())
# find names used but not defined at module level (rough check for typos)
defined = set(dir(__builtins__)) | {'json','re','sys'}
for node in tree.body:
    if isinstance(node, (ast.FunctionDef, ast.ClassDef)):
        defined.add(node.name)
    elif isinstance(node, ast.Assign):
        for t in node.targets:
            if isinstance(t, ast.Name): defined.add(t.id)
    elif isinstance(node, ast.AnnAssign) and isinstance(node.target, ast.Name):
        defined.add(node.target.id)
used = set()
for node in ast.walk(tree):
    if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load):
        used.add(node.id)
import builtins
unknown = used - defined - set(dir(builtins))
print("possibly undefined:", sorted(unknown))
PYEOF
